import{_ as p,c as i,o as e,ah as l}from"./chunks/framework.Ch_PcVtW.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART0/はじめに/tmp_context_input.md","filePath":"scripts/output/PART0/はじめに/tmp_context_input.md"}'),a={name:"scripts/output/PART0/はじめに/tmp_context_input.md"};function o(r,t,_,s,n,c){return e(),i("div",null,[...t[0]||(t[0]=[l('<p>你是出版项目统筹编辑。</p><p>全局背景信息： 这是一本由日经出版社和bmsg会社合作的连载文集，名为日高光启的管理学，以第一人称的短篇记录形式，结合第三人称的客观介绍，主要跟踪采访了bmsg公司的动向，和日高光启作为ceo和唱跳团体制作人的思考和评价，以及他本人的个人活动，和对行业的一些观点。日高光启本人作为rapper思维活跃，并接受过良好教育，待人平等和蔼，所以本文中语气既有作为专业管理者的一丝不苟和客观严谨，又有作为艺术家和艺术工作者的通情达理、充满激情和想象力。日经出版社作为常年观察bmsg公司动向的出版社，和日高的合作紧密。本书中涉及很多音乐专业和行业特有词汇，如果遇到英文可以保持英文并在括号中注释为常用中文。</p><h2 id="以下是本篇原文" tabindex="-1">以下是本篇原文： <a class="header-anchor" href="#以下是本篇原文" aria-label="Permalink to &quot;以下是本篇原文：&quot;">​</a></h2><p>はじめに</p><p>大層なサブタイトルに引かれてくださった方には拍子抜けかもしれませんが、実際のところ世界と日本の音楽業界に「壁」なんてものは、現在は存在しないのですよね。その前提だけお伝えできればこの前書きは役目を果たしているのですが、もう少し詳しく話しましょう。まずはそのために自己紹介をさせてください。</p><p>初めましての方は初めまして、そうでない方はいつもありがとうございます株式会社BMSG代表取締役CEOの日高と申します。またSKY-HIと言う名前で10代の頃からラッパーとしてキャリアを積んだり、2021年からはBE:FIRSTをはじめとしたボーイズグループのプロデューサーなどもしています。3つの肩書きを同時進行する毎日は、刺激的と言うか不安と幸福が縄の如くの日々です。奇特な人生ですね。</p><p>他に日高光啓と言う名前でAAAというグループを20年ほどやっていたり(現在活動休止中)、もっと遡れば中学生の頃から芸能活動をしていましたが、この期間、</p><ul><li>国内最大手事務所のアイドルの練習生</li><li>バンドマン</li><li>別の大手事務所の練習生</li><li>AAA</li><li>アンダーグラウンドのラッパー</li><li>インディーズレーベルのヘッド</li><li>BMSG起業</li><li>プロデューサー業</li></ul><p>と音楽業界と芸能界を渡り歩き、特にラッパーや作曲家としてはインディメジャー問わずに国内のほとんどの音楽関係の会社さんとはお仕事をしてきたと思いますし、海外のアーティストと作品を作ったりワールドツアーを回ったりと、書けば書くほどまぁ懲りずに色んな事をやってきたな・・・。</p><p>本来アーティストは1つのことのために黙々とスタイルを磨き続けるほうがカッコ良いのですが、この多動症が幸か不幸か音楽業界の解像度を上げました。</p><p>そして一番驚くのは、これだけ色々なことをしてきた期間・・・自分が起業するまでの約20年の間、日本の音楽ビジネスの根本的構造や芸能界の体質は、変わらずに来ていたことです。</p><p>日本と世界の音楽シーンにあるのは、壁なんかではありません。ただの「時差」です。そしてインターネットという発明は世界の時差を(良くも悪くも)なくす発明ですから、日本の音楽が世界中で聴かれるルートというのはもう存在してるんですよね。というか聴いている人なんて実際にもういっぱいいるし。</p><p>なぜこの道を皆で渡れないのか、なんでBMSGは渡れると思って意気揚々と準備をしているのか、本著でその辺りが伝われば・・・そしてあなたの中の常識を変える事ができれば、さらにそれがつながって広がっていけば、たどり着く先はおのずとこの世界中です。さて、パスポートの用意をしていてください!</p><hr><p>请输出：</p><ol><li>本篇主题与主要内容概述（150~300字）</li><li>人物/术语/语气风险点（要点列出）</li><li>翻译时建议重点</li></ol>',16)])])}const d=p(a,[["render",o]]);export{m as __pageData,d as default};
